package com.hbm.client.solarboiler;
import com.hbm.machine.solarboiler.*;import com.hbm.client.gui.font.LegacyFonts;import net.minecraft.client.Minecraft;import net.minecraft.network.chat.Component;import net.minecraft.world.phys.BlockHitResult;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.RenderGuiEvent;
@EventBusSubscriber(modid="hbm",value=Dist.CLIENT)
public final class SolarBoilerOverlay {
 @SubscribeEvent public static void render(RenderGuiEvent.Post event){var mc=Minecraft.getInstance();if(mc.options.hideGui||mc.level==null||!(mc.hitResult instanceof BlockHitResult hit)||!(mc.level.getBlockState(hit.getBlockPos()).getBlock() instanceof SolarBoilerBlock block))return;var pos=block.findCore(mc.level,hit.getBlockPos());if(pos==null||!(mc.level.getBlockEntity(pos) instanceof SolarBoilerBlockEntity boiler))return;var g=event.getGuiGraphics();int x=g.guiWidth()/2+8,y=g.guiHeight()/2-10;var font=LegacyFonts.get();{g.drawString(font,Component.translatable("block.hbm.machine_solar_boiler"),x,y,0xffff00,true);y+=12;for(var tank:boiler.getAllTanks()){g.fill(x+1,y+1,x+1+(int)(178D*tank.getFill()/tank.getMaxFill()),y+11,0xa0000000|tank.getTankType().getColor()&0xffffff);g.drawString(font,tank.getTankType().displayName().copy().append(" "+tank.getFill()+"/"+tank.getMaxFill()+"mB"),x+2,y+1,0xffffff,true);y+=14;}}if(boiler.display<1)g.drawString(font,Component.translatable("gui.hbm.solar_boiler.cold"),x,y,System.currentTimeMillis()%1000<500?0xff0000:0xffff00,true);}
 private SolarBoilerOverlay(){}
}
